def reverse_words(text: str) -> str:
    """Return *text* with the order of its whitespace-separated words reversed. Runs of
    whitespace collapse to a single space and leading/trailing whitespace is dropped.
    """
    return ' '.join(reversed(text.split()))

def count_vowels(text: str) -> int:
    """Return how many of the letters a, e, i, o and u occur in *text*, ignoring case.
    """
    return sum(1 for c in text.lower() if c in 'aeiou')

def capitalize_words(text: str) -> str:
    """Upper-case the first character of every whitespace-separated word and lower-case
    the rest. Whitespace between words is preserved exactly.
    """
    import re
    return re.sub(r'\S+', lambda m: m.group(0)[:1].upper() + m.group(0)[1:].lower(), text)

def truncate(text: str, limit: int) -> str:
    """Return *text* unchanged when it is at most *limit* characters long. Otherwise cut
    it so the result including the trailing '...' is exactly *limit* characters. When
    *limit* is 3 or less, return the first *limit* characters of '...'.
    """
    if len(text) <= limit:
        return text
    if limit <= 3:
        return '...'[:limit]
    return text[:limit - 3] + '...'

def longest_word(text: str) -> str:
    """Return the longest whitespace-separated word in *text*. On a tie return the one
    that occurs first. Return '' for text with no words.
    """
    best = ''
    for word in text.split():
        if len(word) > len(best):
            best = word
    return best

def dedupe_chars(text: str) -> str:
    """Return *text* with later occurrences of a character removed, keeping the first
    occurrence in place. The comparison is case sensitive.
    """
    seen = set()
    out = []
    for c in text:
        if c not in seen:
            seen.add(c)
            out.append(c)
    return ''.join(out)

def char_frequency(text: str) -> dict:
    """Return a dict mapping each non-whitespace character of *text* to how often it
    occurs. Case is significant.
    """
    counts = {}
    for c in text:
        if not c.isspace():
            counts[c] = counts.get(c, 0) + 1
    return counts

