def snake_to_camel(name: str) -> str:
    """Convert a snake_case identifier to camelCase. Leading underscores are preserved,
    repeated underscores are treated as one separator, and a trailing underscore is
    dropped.
    """
    lead = len(name) - len(name.lstrip('_'))
    parts = [p for p in name.strip('_').split('_') if p]
    if not parts:
        return name[:lead]
    return '_' * lead + parts[0] + ''.join(p[:1].upper() + p[1:] for p in parts[1:])

def is_anagram(a: str, b: str) -> bool:
    """Return True when *a* and *b* contain the same letters with the same counts,
    ignoring case and every non-letter character.
    """
    def key(s):
        return sorted(c for c in s.lower() if c.isalpha())
    return key(a) == key(b)

def compress(text: str) -> str:
    """Run-length encode *text*: every run of the same character becomes the character
    followed by the run length, but runs of length 1 keep no number. Return '' for ''.
    """
    if not text:
        return ''
    out = []
    current, count = text[0], 1
    for c in text[1:]:
        if c == current:
            count += 1
        else:
            out.append(current + (str(count) if count > 1 else ''))
            current, count = c, 1
    out.append(current + (str(count) if count > 1 else ''))
    return ''.join(out)

def caesar(text: str, shift: int) -> str:
    """Shift every ASCII letter of *text* by *shift* places through the alphabet, wrapping
    around and preserving case. Non-letters are returned unchanged. A negative shift
    shifts backwards.
    """
    out = []
    for c in text:
        if 'a' <= c <= 'z':
            out.append(chr((ord(c) - 97 + shift) % 26 + 97))
        elif 'A' <= c <= 'Z':
            out.append(chr((ord(c) - 65 + shift) % 26 + 65))
        else:
            out.append(c)
    return ''.join(out)

def normalise_whitespace(text: str) -> str:
    """Collapse every run of whitespace in *text* to a single space and strip the ends.
    """
    return ' '.join(text.split())

def flatten_once(items: list) -> list:
    """Flatten one level: elements that are lists are spliced in, everything else is kept
    as it is. Strings are never flattened.
    """
    out = []
    for item in items:
        if isinstance(item, list):
            out.extend(item)
        else:
            out.append(item)
    return out

def drop_consecutive_duplicates(items: list) -> list:
    """Remove elements that are equal to the element directly before them.
    """
    out = []
    for item in items:
        if not out or item != out[-1]:
            out.append(item)
    return out

def interleave(a: list, b: list) -> list:
    """Alternate elements of *a* and *b*, starting with *a*. When one list is longer, its
    remaining elements are appended in order.
    """
    out = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            out.append(a[i])
        if i < len(b):
            out.append(b[i])
    return out

def top_k_frequent(items: list, k: int) -> list:
    """Return the *k* most frequent elements, most frequent first. Ties are broken by
    first appearance in *items*. When *k* exceeds the number of distinct elements,
    return all of them.
    """
    order = {}
    counts = {}
    for i, item in enumerate(items):
        counts[item] = counts.get(item, 0) + 1
        order.setdefault(item, i)
    ranked = sorted(counts, key=lambda x: (-counts[x], order[x]))
    return ranked[:k]

def longest_increasing_run(numbers: list) -> list:
    """Return the longest run of strictly increasing consecutive elements. On a tie return
    the earliest such run. An empty input gives an empty list.
    """
    best = []
    current = []
    for x in numbers:
        if current and x > current[-1]:
            current.append(x)
        else:
            current = [x]
        if len(current) > len(best):
            best = list(current)
    return best

def move_zeros(numbers: list) -> list:
    """Return a new list with every 0 moved to the end, other elements keeping their
    relative order.
    """
    kept = [x for x in numbers if x != 0]
    return kept + [0] * (len(numbers) - len(kept))

def index_of_min(numbers: list) -> int:
    """Return the index of the smallest element, the earliest one on a tie. Return -1 for
    an empty list.
    """
    if not numbers:
        return -1
    best = 0
    for i, x in enumerate(numbers):
        if x < numbers[best]:
            best = i
    return best

def invert(mapping: dict) -> dict:
    """Return a dict with keys and values swapped. When two keys share a value, the key
    that comes later in iteration order wins.
    """
    return {v: k for k, v in mapping.items()}

