def nested_get(data: dict, path: str, default=None):
    """Look up a dotted *path* such as 'a.b.c' in nested dicts. Return *default* when any
    step is missing or when a step runs into something that is not a dict. An empty
    path returns *data*.
    """
    if path == '':
        return data
    current = data
    for key in path.split('.'):
        if not isinstance(current, dict) or key not in current:
            return default
        current = current[key]
    return current

def sum_by_prefix(mapping: dict, prefix: str) -> float:
    """Add up the values of every entry whose key starts with *prefix*.
    """
    return sum(v for k, v in mapping.items() if k.startswith(prefix))

def most_common_key(counts: dict) -> str | None:
    """Return the key with the largest value, breaking ties by the smaller key. Return
    None for an empty dict.
    """
    if not counts:
        return None
    return min(counts, key=lambda k: (-counts[k], k))

