def lcm_of(a: int, b: int) -> int:
    """Return the least common multiple of two positive integers. Return 0 when either is 0.
    """
    if a == 0 or b == 0:
        return 0
    x, y = a, b
    while y:
        x, y = y, x % y
    return a * b // x

def is_prime(n: int) -> bool:
    """Return True when *n* is a prime number. Numbers below 2 are not prime.
    """
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def digit_sum(n: int) -> int:
    """Return the sum of the decimal digits of *n*. Negative numbers use their absolute
    value.
    """
    return sum(int(c) for c in str(abs(n)))

def fizz_list(n: int) -> list:
    """Return the FizzBuzz list for 1..n: multiples of 3 become 'Fizz', of 5 'Buzz', of
    both 'FizzBuzz', everything else the number as a string.
    """
    out = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            out.append('FizzBuzz')
        elif i % 3 == 0:
            out.append('Fizz')
        elif i % 5 == 0:
            out.append('Buzz')
        else:
            out.append(str(i))
    return out

def factorial(n: int) -> int:
    """Return n! computed iteratively. factorial(0) is 1. Raise ValueError for negative n.
    """
    if n < 0:
        raise ValueError('n must not be negative')
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def median(numbers: list) -> float:
    """Return the median of *numbers*. For an even count return the mean of the two middle
    values. Raise ValueError for an empty list.
    """
    if not numbers:
        raise ValueError('numbers must not be empty')
    ordered = sorted(numbers)
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return float(ordered[mid])
    return (ordered[mid - 1] + ordered[mid]) / 2

def clamp(value: float, low: float, high: float) -> float:
    """Return *value* limited to the range [low, high]. Raise ValueError when low > high.
    """
    if low > high:
        raise ValueError('low must not exceed high')
    return max(low, min(value, high))

def to_base(n: int, base: int) -> str:
    """Render the non-negative integer *n* in *base* (2 to 16) using digits 0-9 then
    lower-case a-f. to_base(0, b) is '0'. Raise ValueError for a base outside 2..16.
    """
    if not 2 <= base <= 16:
        raise ValueError('base must be between 2 and 16')
    if n == 0:
        return '0'
    digits = '0123456789abcdef'
    out = []
    while n:
        out.append(digits[n % base])
        n //= base
    return ''.join(reversed(out))

def is_perfect_square(n: int) -> bool:
    """Return True when *n* is the square of a whole number. Negative numbers are never
    perfect squares.
    """
    if n < 0:
        return False
    root = int(n ** 0.5)
    for candidate in (root - 1, root, root + 1):
        if candidate >= 0 and candidate * candidate == n:
            return True
    return False

def count_divisors(n: int) -> int:
    """Return how many positive divisors the positive integer *n* has, including 1 and n.
    Raise ValueError when n is not positive.
    """
    if n < 1:
        raise ValueError('n must be positive')
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            count += 2 if i * i != n else 1
        i += 1
    return count

def percent_change(old: float, new: float) -> float | None:
    """Return the percentage change from *old* to *new*. Return None when *old* is 0.
    """
    if old == 0:
        return None
    return (new - old) / old * 100

def parse_kv(text: str) -> dict:
    """Parse 'a=1;b=2' into {'a': '1', 'b': '2'}. Empty segments are skipped, surrounding
    whitespace is stripped from keys and values, and a segment with no '=' is ignored.
    Only the first '=' separates key from value.
    """
    out = {}
    for part in text.split(';'):
        if '=' not in part:
            continue
        key, _, value = part.partition('=')
        key = key.strip()
        if key:
            out[key] = value.strip()
    return out

