def parse_csv_line(line: str) -> list:
    """Split one CSV line into fields. A field may be wrapped in double quotes, in which
    case it may contain commas, and a doubled quote inside means a literal quote.
    Unquoted fields are taken as they are. An empty line gives ['']. 
    """
    fields = []
    current = []
    in_quotes = False
    i = 0
    while i < len(line):
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    current.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                current.append(c)
        elif c == '"':
            in_quotes = True
        elif c == ',':
            fields.append(''.join(current))
            current = []
        else:
            current.append(c)
        i += 1
    fields.append(''.join(current))
    return fields

def parse_version(text: str) -> tuple:
    """Parse 'MAJOR.MINOR.PATCH' into a tuple of three ints. Missing components default to
    0, so '1.2' is (1, 2, 0). Raise ValueError when a component is not a number or
    when there are more than three.
    """
    parts = text.split('.')
    if len(parts) > 3:
        raise ValueError('too many components')
    numbers = []
    for part in parts:
        if not part.isdigit():
            raise ValueError('bad component: ' + part)
        numbers.append(int(part))
    while len(numbers) < 3:
        numbers.append(0)
    return tuple(numbers)

