def parse_ini_section(text: str, section: str) -> dict:
    """Return the key/value pairs of one [section] of an INI-style text. Lines starting
    with '#' or ';' and blank lines are ignored, keys and values are stripped, and a
    missing section gives {}.
    """
    out = {}
    current = None
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in '#;':
            continue
        if line.startswith('[') and line.endswith(']'):
            current = line[1:-1].strip()
            continue
        if current == section and '=' in line:
            key, _, value = line.partition('=')
            out[key.strip()] = value.strip()
    return out

