def split_name(full: str) -> tuple:
    """Split a full name into (first, last). With one word the last name is ''. With more
    than two words everything between first and last belongs to the first name.
    """
    parts = full.split()
    if not parts:
        return ('', '')
    if len(parts) == 1:
        return (parts[0], '')
    return (' '.join(parts[:-1]), parts[-1])

def parse_range_list(text: str) -> list:
    """Expand '1-3,5,7-8' into [1, 2, 3, 5, 7, 8]. Whitespace is ignored, the result is
    sorted and free of duplicates, and a reversed range such as '5-3' raises
    ValueError, as does any non-numeric part.
    """
    values = set()
    for part in text.replace(' ', '').split(','):
        if not part:
            continue
        if '-' in part[1:]:
            start, _, end = part.partition('-')
            if not start.isdigit() or not end.isdigit():
                raise ValueError('bad range: ' + part)
            if int(start) > int(end):
                raise ValueError('reversed range: ' + part)
            values.update(range(int(start), int(end) + 1))
        else:
            if not part.isdigit():
                raise ValueError('bad number: ' + part)
            values.add(int(part))
    return sorted(values)

