answer:
def strip_comments(text: str) -> str:
    """Remove '#' comments from every line, keeping the code before the '#' with trailing
    whitespace stripped. Lines that become empty are dropped entirely. A '#' inside a
    single-quoted string still counts as a comment for this simplified version.
    """
    out = []
    for line in text.splitlines():
        code = line.split('#', 1)[0].rstrip()
        if code.strip():
            out.append(code)
    return '\n'.join(out)

def flatten_deep(items: list) -> list:
    """Flatten an arbitrarily nested list into a flat list, preserving order. Strings are
    never flattened.
    """
    out = []
    for item in items:
        if isinstance(item, list):
            out.extend(flatten_deep(item))
        else:
            out.append(item)
    return out

def power(base: float, exponent: int) -> float:
    """Compute base ** exponent recursively for a non-negative integer exponent, without
    using the ** operator or pow().
    """
    if exponent == 0:
        return 1
    half = power(base, exponent // 2)
    return half * half * (base if exponent % 2 else 1)

def count_leaves(node: dict) -> int:
    """Count the leaves of a tree where a node is {'children': [...]}. A node with no
    children, or with an empty list, is a leaf.
    """
    children = node.get('children') or []
    if not children:
        return 1
    return sum(count_leaves(child) for child in children)

def binary_search_rec(items: list, target) -> int:
    """Return the index of *target* in the sorted list *items* using recursion, or -1 when
    it is absent. Any matching index is acceptable when there are duplicates.
    """
    def go(lo, hi):
        if lo > hi:
            return -1
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            return go(mid + 1, hi)
        return go(lo, mid - 1)
    return go(0, len(items) - 1)

def collatz_steps(n: int) -> int:
    """Count how many steps it takes to reach 1: even numbers are halved, odd numbers
    become 3n+1. collatz_steps(1) is 0. Raise ValueError for n below 1.
    """
    if n < 1:
        raise ValueError('n must be at least 1')
    if n == 1:
        return 0
    return 1 + collatz_steps(n // 2 if n % 2 == 0 else 3 * n + 1)

def tree_depth(node: dict) -> int:
    """Return the depth of a tree where a node is {'children': [...]}. A single node has
    depth 1.
    """
    children = node.get('children') or []
    if not children:
        return 1
    return 1 + max(tree_depth(child) for child in children)

def reverse_rec(text: str) -> str:
    """Reverse a string recursively, without slicing the whole string with [::-1].
    """
    if len(text) <= 1:
        return text
    return reverse_rec(text[1:]) + text[0]

def count_paths(rows: int, cols: int) -> int:
    """Count the shortest paths across a grid of *rows* by *cols* blocks when only moves
    east and north are allowed. A grid with a zero dimension has exactly one path.
    """
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def go(r, c):
        if r == 0 or c == 0:
            return 1
        return go(r - 1, c) + go(r, c - 1)
    return go(rows, cols)

def gcd_rec(a: int, b: int) -> int:
    """Return the greatest common divisor of two non-negative integers using recursion.
    """
    return a if b == 0 else gcd_rec(b, a % b)

def binary_search(items: list, target) -> int:
    """Return the index of the FIRST occurrence of *target* in the sorted list *items*, or
    -1 when it is absent.
    """
    lo, hi = 0, len(items) - 1
    found = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            found = mid
            hi = mid - 1
        elif items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
