def min_coins(amount: int, coins: list) -> int:
    """Return the fewest coins that add up to *amount*, or -1 when it cannot be made. Coins
    may be used any number of times. min_coins(0, ...) is 0.
    """
    best = [0] + [float('inf')] * amount
    for value in range(1, amount + 1):
        for coin in coins:
            if coin <= value and best[value - coin] + 1 < best[value]:
                best[value] = best[value - coin] + 1
    return -1 if best[amount] == float('inf') else int(best[amount])

