def wrap_text(text: str, width: int) -> list:
    """Wrap *text* into lines of at most *width* characters, breaking only at spaces and
    never splitting a word. A word longer than *width* gets a line of its own. Runs of
    whitespace collapse; empty input gives an empty list. Raise ValueError when width
    is below 1.
    """
    if width < 1:
        raise ValueError('width must be at least 1')
    lines, current = [], ''
    for word in text.split():
        candidate = f'{current} {word}' if current else word
        if len(candidate) <= width or not current:
            current = candidate
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return lines

