def prime_factors(n: int) -> list:
    """Return the prime factors of *n* in ascending order, repeating a factor as often as
    it divides. prime_factors(1) is []. Raise ValueError for n below 1.
    """
    if n < 1:
        raise ValueError('n must be positive')
    factors = []
    divisor = 2
    while divisor * divisor <= n:
        while n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        divisor += 1
    if n > 1:
        factors.append(n)
    return factors

def parse_size(text: str) -> int:
    """Parse a size such as '1.5MB' or '512' into whole bytes, rounded down. Suffixes are
    B, KB, MB and GB, case insensitive, each 1024 times the one before; a missing
    suffix means bytes. Raise ValueError for anything else.
    """
    import re
    match = re.fullmatch(r'\s*(\d+(?:\.\d+)?)\s*([KMG]?B?)\s*', text, re.IGNORECASE)
    if not match:
        raise ValueError('bad size: ' + text)
    factors = {'': 1, 'B': 1, 'K': 1024, 'KB': 1024, 'M': 1024 ** 2, 'MB': 1024 ** 2,
               'G': 1024 ** 3, 'GB': 1024 ** 3}
    return int(float(match.group(1)) * factors[match.group(2).upper()])

