def parse_flags(argv: list) -> dict:
    """Parse a simple argument list. '--name=value' and '--name value' both map name to
    the value; a flag with no value maps to True. Leading dashes are stripped from
    the key. Arguments that are not flags are ignored.
    """
    out = {}
    i = 0
    while i < len(argv):
        token = argv[i]
        if token.startswith('-'):
            key, sep, value = token.lstrip('-').partition('=')
            if sep:
                out[key] = value
            elif i + 1 < len(argv) and not argv[i + 1].startswith('-'):
                out[key] = argv[i + 1]
                i += 1
            else:
                out[key] = True
        i += 1
    return out

