def permutations_of(items: list) -> list:
    """Return every permutation of *items* as a list of tuples, sorted ascending, using
    recursion and without itertools. An empty input gives [()].
    """
    if not items:
        return [()]
    out = []
    for i, item in enumerate(items):
        rest = items[:i] + items[i + 1:]
        out.extend((item, *tail) for tail in permutations_of(rest))
    return sorted(out)

def count_down(n: int) -> list:
