def lcs_length(a: str, b: str) -> int:
    """Return the length of the longest common subsequence of two strings.
    """
    previous = [0] * (len(b) + 1)
    for x in a:
        current = [0]
        for j, y in enumerate(b):
            current.append(previous[j] + 1 if x == y else max(previous[j + 1], current[j]))
        previous = current
    return previous[-1]

def normalise_bool(value, default: bool = False) -> bool:
    """Coerce a value to a boolean: real booleans pass through, numbers use 0 as False,
    strings accept true/yes/y/on/1 and false/no/n/off/0 case insensitively, and
    anything else (including None) returns *default*.
    """
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    if isinstance(value, str):
        text = value.strip().lower()
        if text in ('true', 'yes', 'y', 'on', '1'):
            return True
        if text in ('false', 'no', 'n', 'off', '0'):
            return False
    return default

